package com.careerverse.servlet;
import com.careerverse.config.DB; import com.careerverse.dao.UserDAO; import com.careerverse.util.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*; import java.time.*;
@WebServlet("/reset-password") public class ResetPasswordServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{s.sendRedirect("reset-password.jsp?token="+r.getParameter("token"));}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{String t=r.getParameter("token"),pw=r.getParameter("password");try(Connection c=DB.getConnection();PreparedStatement q=c.prepareStatement("SELECT id,user_id FROM password_reset_tokens WHERE token_hash=? AND used=false AND expires_at>? ORDER BY id DESC LIMIT 1")){q.setString(1,TokenUtil.sha256(t));q.setTimestamp(2,Timestamp.from(Instant.now()));try(ResultSet rs=q.executeQuery()){if(!rs.next()){s.sendRedirect("reset-password.jsp?error=Invalid+or+expired+link");return;}int tokenId=rs.getInt(1),uid=rs.getInt(2);UserDAO.changePassword(uid,PasswordUtil.hash(pw));try(PreparedStatement u=c.prepareStatement("UPDATE password_reset_tokens SET used=true WHERE id=?")){u.setInt(1,tokenId);u.executeUpdate();}s.sendRedirect("login.jsp?reset=1");}}catch(Exception e){s.sendRedirect("reset-password.jsp?error=Could+not+reset");}}}
